import{_ as r,o as n,c as t,ak as a}from"./chunks/framework.CYL5YPWS.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"prev":false,"next":false,"title":"FAQ"},"headers":[],"relativePath":"guides/faq.md","filePath":"guides/faq.md"}'),o={name:"guides/faq.md"};function s(i,e,l,d,p,c){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="open-grind-faq" tabindex="-1">Open Grind FAQ <a class="header-anchor" href="#open-grind-faq" aria-label="Permalink to “Open Grind FAQ”">​</a></h1><h2 id="open-grind-status" tabindex="-1">Open Grind status <a class="header-anchor" href="#open-grind-status" aria-label="Permalink to “Open Grind status”">​</a></h2><details class="details custom-block"><summary>How to download Open Grind APK?</summary><p><strong>Follow instructions at <a href="/guides/download">https://opengrind.org/download</a></strong>. Do not download apk files outside of the official pages. If you&#39;re an advanced technical user, consider <a href="https://git.opengrind.org/open-grind/open-grind/src/branch/main/BUILDING.md#build-open-grind" target="_blank" rel="noreferrer">building Open Grind</a> yourself on your computer.</p></details><details class="details custom-block"><summary>When will an “X” feature be available? When does the next update come out?</summary><p>Visit <a href="https://git.opengrind.org/open-grind/open-grind/issues" target="_blank" rel="noreferrer">issues tracker</a> to search for a specific feature and track its status.</p><p>Visit <a href="https://git.opengrind.org/open-grind/open-grind/milestones" target="_blank" rel="noreferrer">milestones</a> to track progress of the next update.</p><p>Join <a href="https://matrix.to/#/#announcements:opengrind.org" target="_blank" rel="noreferrer">#announcements:opengrind.org</a> to get announcements about new releases.</p><p>Join <a href="https://matrix.to/#/#dev:opengrind.org" target="_blank" rel="noreferrer">#dev:opengrind.org</a> to follow the project development progress.</p></details><details class="details custom-block"><summary>Can I pay to gain access to the testing phase early? Or to speed up development?</summary><p>No, <strong>Open Grind is 100% free, transparent and will always be</strong>. No crypto, no NFTs, no merch, no paid versions, no community badges, no paid support, nothing at all. It&#39;s literally impossible to give money to Open Grind project. Anyone who claims otherwise is a scammer.</p><p>If you do intend to voluntarily donate money as a thank-you <strong>to particular contributors</strong>, refer to <a href="https://git.opengrind.org/open-grind/open-grind/src/branch/main/FUNDING.md" target="_blank" rel="noreferrer">FUNDING.md</a> file to find a list of donation links for each individual contributor.</p><p>Donations are optional, won&#39;t grant any privileges, and <strong>there is no single governance entity that accepts donations on Open Grind&#39;s behalf.</strong></p></details><details class="details custom-block"><summary>How many users does Open Grind have?</summary><p>We genuinely have no idea, and it&#39;s a good thing: there are exactly zero trackers, analytics, data collection in the app. There is no &quot;ping&quot;, no &quot;install counter&quot;, nothing that reports back that you exist; Grindr can&#39;t infer that either because Open Grind strives to be stealthy and mask itself in the official app disguise.</p><p>The only indirect counters are:</p><ol><li>Download count on Releases page <ul><li>It <strong>does not track IP address</strong>, it&#39;s a simple integer counter that is increased each time someone sends the HTTP request to download the file. Nothing about the request is logged or stored.</li></ul></li><li>Number of joined accounts in the official discussion venues <ul><li>Such as number of participants in the official Matrix chat room (no limit on how many accounts a person can have or which homeservers they join from)</li><li>Number of registered users on git.opengrind.org (<strong>IP addresses are not stored</strong>)</li><li>Keep in mind these platforms do not collect or store any personally identifiable data about users</li></ul></li></ol><p>Open Grind has opt-in auto-updater that sends an anonymous request to git.opengrind.org, but these requests are not logged or stored. If you installed the app from F-Droid, Obtainium, Aurora Store or Google Play, the auto-updater is disabled entirely and this does not apply to you. The first-run screen presents this choice with the checkbox pre-checked, nothing is sent until you confirm, and you can change it any time in Settings → App.</p><p><strong>As of September 1st, 2026, the estimated number of users is ~67 000 based on the downloads counter.</strong></p></details><h2 id="open-grind-features" tabindex="-1">Open Grind features <a class="header-anchor" href="#open-grind-features" aria-label="Permalink to “Open Grind features”">​</a></h2><details class="details custom-block"><summary>Is Open Grind similar to GrindrPlus?</summary><p><strong>Open Grind is not affiliated with GrindrPlus.</strong> GrindrPlus project is dead after the developers shut down all resources in May 2026. There is no support for GrindrPlus installation issues in this chat.</p><p>GrindrPlus was a modified version of Grindr application. Open Grind is a completely separate third-party client that&#39;s written from scratch. Any features from Grindr&#39;s official app have to be developed from scratch in the app, but that also means no patches are necessary to remove bloat from the official version.</p><p>Open Grind is completely free, open source and transparent: no ads, no purchases, no trackers, licensed under MIT software license. <strong>Open Grind is not a fork.</strong> However, many projects started from Open Grind&#39;s foundation and some are considered forks <em>of</em> Open Grind.</p></details><details class="details custom-block"><summary>What about other apps such as Free Grind and GrindrX?</summary><p>These are forks of Open Grind building upon its foundation. Neither are affiliated/verified/endorsed by Open Grind developers. All third-party clients put your personal sensitive information at risk. Avoid using Grindr clients that weren&#39;t audited independently, as they might contain spyware.</p><p>Open Grind is 100% transparent and has <a href="https://git.opengrind.org/open-grind/open-grind/src/branch/main/REPRODUCIBILITY.md" target="_blank" rel="noreferrer">reproducible builds</a>, so each published release can be proved to have been built from a given publicly available code snapshot.</p></details><details class="details custom-block"><summary>Is Open Grind a new platform? Is Open Grind similar to Grindr Web? What&#39;s MVP?</summary><p>Grindr Web is a client application, it&#39;s what allows you to access Grindr, i.e. its interface. Open Grind is a client application too. MVP is just a version type, i.e. v0.1.0, defining bare minimum functionality for daily Grindr use.</p><p>It&#39;s not possible to run Open Grind in a web browser. There&#39;s a <strong><a href="https://git.opengrind.org/open-grind/grindr-web-unlock" target="_blank" rel="noreferrer">Grindr Web Unlock</a> project</strong> by Open Grind developers (available for all browsers), that puts best efforts to remove client-side paywalls on web.grindr.com, but does have some known issues and limitations.</p></details><details class="details custom-block"><summary>Is location spoofing possible? Can you fake your geolocation?</summary><p>Yes, it&#39;s built-in. You must explicitly choose a location before you can use Open Grind. On mobile platforms you can also auto-update your location in real time using your device&#39;s GPS.</p><p>See <a href="/guides/features/location-spoofing-teleport">Location spoofing</a></p></details><details class="details custom-block"><summary>Is it possible to bypass age verification?</summary><p><strong>Open Grind does not implement age verification flow and does not have any means of bypassing it. There will be no attempt at integrating any logic related to age verification in the app.</strong> If your account was locked due to age verification laws, you&#39;re advised to download the official app once and complete verification there.</p><p>If you&#39;re unable to comply with the age verification laws because you&#39;re underage, you&#39;re strongly advised against attempting to bypass it or manifesting in any public communities or forums affiliated with Open Grind.</p></details><details class="details custom-block"><summary>Does Open Grind bypass bans?</summary><p>There are no features that aim specifically at bypassing account bans in Open Grind. However, some Open Grind features indirectly assist in this, such as random device id and zero trackers to link multiple accounts to single person.</p></details><details class="details custom-block"><summary>How to create an account?</summary><p>Currently not possible. Follow <a href="https://git.opengrind.org/open-grind/open-grind/issues/21" target="_blank" rel="noreferrer">#21</a> for updates. Use the official app to create an account and then sign in to Open Grind.</p></details><details class="details custom-block"><summary>How to sign in with Google?</summary><p>See <a href="https://opengrind.org/guides/sign-in-with-google" target="_blank" rel="noreferrer">https://opengrind.org/guides/sign-in-with-google</a></p></details><details class="details custom-block"><summary>How to sign in with Facebook?</summary><p>Currently not possible. Follow <a href="https://git.opengrind.org/open-grind/open-grind/issues/88" target="_blank" rel="noreferrer">#88</a> for updates.</p></details><details class="details custom-block"><summary>How to sign in with a phone number?</summary><p>Currently not possible. Track <a href="https://git.opengrind.org/open-grind/open-grind/issues/29" target="_blank" rel="noreferrer">https://git.opengrind.org/open-grind/open-grind/issues/29</a> to follow updates.</p></details><details class="details custom-block"><summary>Are there any AI features in Open Grind?</summary><p>No, and likely will never be.</p></details><h2 id="open-grind-development" tabindex="-1">Open Grind development <a class="header-anchor" href="#open-grind-development" aria-label="Permalink to “Open Grind development”">​</a></h2><details class="details custom-block"><summary>How can I help development?</summary><ul><li><strong>Developers, testers, reverse engineering devs:</strong> Get involved and <a href="https://git.opengrind.org/open-grind/open-grind/src/branch/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">contribute code</a>.</li><li><strong>Everyone else:</strong> Spread the word. Share the link to Open Grind. Tell your friends about it.</li></ul></details><details class="details custom-block"><summary>What are the community rules for discussion chat rooms?</summary><p>See <a href="https://git.opengrind.org/open-grind/open-grind/src/branch/main/CODE_OF_CONDUCT.md" target="_blank" rel="noreferrer">CODE_OF_CONDUCT.md</a></p></details><details class="details custom-block"><summary>Is it possible to customize colors of the UI?</summary><p>Currently not possible. Follow <a href="https://git.opengrind.org/open-grind/open-grind/issues/230" target="_blank" rel="noreferrer">#230</a> for updates.</p></details><h2 id="common-issues-other-questions" tabindex="-1">Common issues &amp; other questions <a class="header-anchor" href="#common-issues-other-questions" aria-label="Permalink to “Common issues &amp; other questions”">​</a></h2><details class="details custom-block"><summary>Cascade shows nearby people mixed with some profiles far away.</summary><p>That&#39;s how items are returned from API, specifically the first ten are &quot;open&quot; and then there&#39;s only profileId, which a client can fetch in bulk. UX improvements are planned for this issue but not in the works yet.</p><p>Follow <a href="https://git.opengrind.org/open-grind/open-grind/issues/149" target="_blank" rel="noreferrer">#149</a> and <a href="https://git.opengrind.org/open-grind/open-grind/issues/150" target="_blank" rel="noreferrer">#150</a> for updates.</p></details><details class="details custom-block"><summary>Is GrindrPlus Discord server gone?</summary><p>Yes, it&#39;s been confirmed that it&#39;s been deleted. In its last weeks, the server was mostly off topic anyway. Any intel regarding Grindr API is welcome in Open Grind&#39;s <a href="https://matrix.to/#/#dev:opengrind.org" target="_blank" rel="noreferrer">#dev:opengrind.org</a>.</p></details><details class="details custom-block"><summary>How to verify a certain build is safe and trusted?</summary><p>Releases are signed with <a href="https://jedisct1.github.io/minisign/" target="_blank" rel="noreferrer">minisign</a> and ship a detached <code>.minisig</code>. The release signing key, and the governance PGP key that certifies it, can be found in <a href="https://git.opengrind.org/open-grind/open-grind/src/branch/main/KEYS.md" target="_blank" rel="noreferrer">KEYS.md</a>.</p><p>You can also <a href="https://git.opengrind.org/open-grind/open-grind/src/branch/main/BUILDING.md#verify-android-release" target="_blank" rel="noreferrer">reproduce the build</a> to verify it came from this source.</p></details>',26)])])}const g=r(o,[["render",s]]);export{m as __pageData,g as default};
